const app = require('./app.js');

describe('POST /users', () => {
  it('should reject requests with missing name field', async () => {
    const res = await request(app)
      .post('/users')
      .send({});
    expect(res.statusCode).toEqual(400);
    expect(res.body).toHaveProperty('error', 'Name is required');
  });

  it('should reject requests with non-string name field', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 123 });
    expect(res.statusCode).toEqual(400);
    expect(res.body).toHaveProperty('error', 'Name must be a string');
  });

  it('should accept requests with a valid name field', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'John' });
    expect(res.statusCode).toEqual(201);
    expect(res.body).toHaveProperty('success', true);
    expect(res.body).toHaveProperty('name', 'John');
  });
});

