const assert = require('assert');
const request = require('supertest');
const app = require('./app.js');

describe('POST /users', () => {
  // Test for valid input
  it('should accept a valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Alice' });

    assert.strictEqual(response.status, 200);
    assert.deepStrictEqual(response.body, { success: true, name: 'Alice' });
  });

  // Test for missing name field
  it('should reject a missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    assert.strictEqual(response.status, 400);
    assert.deepStrictEqual(response.body, { error: 'The "name" field is required and must be a string.' });
  });

  // Test for non-string name field
  it('should reject a non-string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    assert.strictEqual(response.status, 400);
    assert.deepStrictEqual(response.body, { error: 'The "name" field is required and must be a string.' });
  });
});

// Run the tests
(async () => {
  try {
    const tests = [
      { name: 'Valid name', fn: () => request(app).post('/users').send({ name: 'Alice' }) },
      { name: 'Missing name', fn: () => request(app).post('/users').send({}) },
      { name: 'Non-string name', fn: () => request(app).post('/users').send({ name: 123 }) },
    ];

    for (const test of tests) {
      console.log(`Running test: ${test.name}`);
      const response = await test.fn();
      console.log(`Status: ${response.status}, Body:`, response.body);
    }

    console.log('\nAll tests completed.');
    process.exit(0);
  } catch (error) {
    console.error('Test failed:', error.message);
    process.exit(1);
  }
})();

