/**
 * Simple validation logic test without dependencies
 * This tests the validation rules самостоятельно from the Express routing
 */

// Mock validation function that matches the logic in app.js
function validateUser(reqBody) {
  const { name } = reqBody;

  if (!name) {
    return { error: 'Missing required field: name' };
  }

  if (typeof name !== 'string') {
    return { error: 'Field "name" must be a string' };
  }

  return { success: true };
}

